async function signIn(e){e.preventDefault();const msg=$("login-msg");if(!supabase){msg.textContent="Portal connection is not ready. Please refresh and try again.";return}msg.textContent="Signing in…";const email=$("login-email").value.trim(),password=$("login-password").value;try{const attempt=supabase.auth.signInWithPassword({email,password});const timeout=new Promise((_,reject)=>setTimeout(()=>reject(new Error("LOGIN_TIMEOUT")),10000));const {error}=await Promise.race([attempt,timeout]);if(error){msg.textContent=error.message;return}await boot()}catch(err){if(err?.message==="LOGIN_TIMEOUT"){msg.textContent="Login is taking too long. Checking your session…";try{const {data,error}=await supabase.auth.getSession();if(!error&&data?.session){await boot();return}}catch{}msg.textContent="The test portal could not reach Supabase Auth. Please refresh once and try again."}else{msg.textContent=err?.message||"Unable to log in. Please try again.";console.error("Portal login error",err)}}}$("login-form").addEventListener("submit",signIn);$("forgot-btn").onclick=async()=>{const email=$("login-email").value.trim();if(!email)return $("login-msg").textContent="Enter your email address first.";const {error}=await supabase.auth.resetPasswordForEmail(email,{redirectTo:location.origin+location.pathname});$("login-msg").textContent=error?error.message:"Password reset instructions have been sent if that email is registered."};$("logout").onclick=async()=>{await supabase?.auth.signOut();location.reload()};
