async function loadPortalIdentities(){const ids=[me?.id,...clients.map(c=>c.id),...messages.map(x=>x.sender_id),...files.map(x=>x.uploaded_by),...timeLogs.map(x=>x.created_by),...tasks.map(x=>x.created_by),...invoices.map(x=>x.created_by)].filter(Boolean),unique=[...new Set(ids)];if(!unique.length)return;const {data,error}=await supabase.rpc("get_portal_identities",{user_ids:unique});if(error){console.error(error);return}portalIdentities=new Map();for(const p of data||[]){let avatar="default-avatar.svg";if(p.avatar_path){const s=await supabase.storage.from("avatars").createSignedUrl(p.avatar_path,3600);avatar=s.data?.signedUrl||avatar}portalIdentities.set(p.id,{...p,avatar})}if(me&&!portalIdentities.has(me.id))portalIdentities.set(me.id,{...me,avatar:"default-avatar.svg"})}
