function viewTask(id){const t=tasks.find(x=>x.id===id);if(!t)return;showModal(`<div class="task-preview"><div class="preview-head"><div><div class="eyebrow">Task details</div><h2>${esc(t.title)}</h2></div><button type="button" class="preview-x" onclick="closeModal()" aria-label="Close preview">×</button></div><div class="task-preview-grid"><div><span>Priority</span><strong><span class="badge ${String(t.priority).toLowerCase()}">${esc(t.priority)}</span></strong></div><div><span>Status</span><strong><span class="badge status-${String(t.status).toLowerCase().replaceAll(" ","-")}">${esc(t.status)}</span></strong></div><div><span>Due</span><strong>${recurringDue(t)}</strong></div><div><span>Hours</span><strong>${Number(t.actual_hours||0).toFixed(2)}</strong></div></div><div class="task-preview-description"><span>Description</span><p>${esc(t.description||"No description provided.")}</p></div><div class="item-owner">Created by ${identityBadge(t.created_by)}</div></div>`)}
