function openTask(id){const t=tasks.find(x=>x.id===id)||{id:"",title:"",description:"",priority:"Normal",status:"Not Started",due_date:"",actual_hours:0,client_id:role==="admin"?(clients.find(c=>c.status!=="Archived")?.client_id||""):me.client_id,recurring_days:[],recurring_end_date:null,recurring_indefinite:false,recurrence_group:null,recurrence_template:false};const priorityField=`<label>Priority<select id="m-priority">${["Urgent","High","Normal","Low"].map(x=>`<option ${x===t.priority?"selected":""}>${x}</option>`).join("")}</select></label>`,dueField=`<label>First / due date<input id="m-due" type="date" value="${t.due_date||""}"></label>`;const adminFields=role==="admin"?`<label>Client<select id="m-client">${clients.filter(c=>c.status!=="Archived").map(c=>`<option value="${c.client_id}" ${c.client_id===t.client_id?"selected":""}>${esc(clientLabel(c.client_id))}</option>`).join("")}</select></label>${priorityField}<label>Status<select id="m-status">${["Not Started","In Progress","Completed"].map(x=>`<option ${x===t.status?"selected":""}>${x}</option>`).join("")}</select>${dueField}<label>Actual hours<input id="m-hours" type="number" step=".25" min="0" value="${t.actual_hours||0}"></label>`:"";const clientCreateFields=role!=="admin"&&!id?`${priorityField}${dueField}`:"";const canManageRecurring=role==="admin"||!id;const isRecurring=!!(t.recurrence_template||t.recurrence_group||(t.recurring_days||[]).length);const recurringField=canManageRecurring?`<fieldset class="recurring-box"><legend>Recurring task</legend><label class="check-row"><input id="m-recurring" type="checkbox" ${isRecurring?"checked":""}> Repeat this task</label><div id="recurring-options" class="${isRecurring?"":"hidden"}"><div class="weekday-picker">${["Mon","Tue","Wed","Thu","Fri","Sat","Sun"].map(x=>`<label><input type="checkbox" name="m-repeat-day" value="${x}" ${(t.recurring_days||[]).includes(x)?"checked":""}> ${x}</label>`).join("")}</div><label class="check-row"><input id="m-indefinite" type="checkbox" ${t.recurring_indefinite?"checked":""}> Continue indefinitely</label><label id="m-end-wrap" class="${t.recurring_indefinite?"hidden":""}">End date<input id="m-repeat-end" type="date" value="${t.recurring_end_date||""}"></label><div class="muted small">Future tasks are created automatically on the selected days. Turning this off stops new occurrences.</div></div></fieldset>`:"";const clientNotice=role!=="admin"&&id?"<div class='notice'>You can update the task title and description. Haus Of Assistants manages priority, status, due date, hours and recurrence after submission.</div>":"";showModal(`<h2>${id?"Edit":"New"} Task</h2><form id="task-form">${adminFields}<label>Title<input id="m-title" required value="${esc(t.title)}"></label><label>Description<textarea id="m-desc">${esc(t.description||"")}</textarea></label>${clientCreateFields}${recurringField}${clientNotice}<button class="primary">Save Task</button></form>`);if($("m-recurring")){$("m-recurring").onchange=()=>{$("recurring-options").classList.toggle("hidden",!$("m-recurring").checked)};$("m-indefinite").onchange=()=>{$("m-end-wrap").classList.toggle("hidden",$("m-indefinite").checked)}}$("task-form").onsubmit=async e=>{e.preventDefault();let payload={title:$("m-title").value.trim(),description:$("m-desc").value};if(role==="admin")Object.assign(payload,{client_id:$("m-client").value,priority:$("m-priority").value,status:$("m-status").value,due_date:$("m-due").value||null,actual_hours:Number($("m-hours").value||0)});else if(!id)Object.assign(payload,{client_id:me.client_id,priority:$("m-priority").value,due_date:$("m-due").value||null});if(canManageRecurring&&$("m-recurring")){if($("m-recurring").checked){const days=[...document.querySelectorAll('input[name="m-repeat-day"]:checked')].map(x=>x.value),indef=$("m-indefinite").checked,end=$("m-repeat-end").value||null;if(!days.length)return flash("Select at least one day for the recurring task.");if(!indef&&!end)return flash("Choose an end date or select continue indefinitely.");Object.assign(payload,{recurring_days:days,recurring_end_date:indef?null:end,recurring_indefinite:indef,recurrence_group:t.recurrence_group||crypto.randomUUID(),recurrence_template:true})}else Object.assign(payload,{recurring_days:[],recurring_end_date:null,recurring_indefinite:false,recurrence_group:null,recurrence_template:false})}const r=id?await supabase.from("tasks").update(payload).eq("id",id):await supabase.from("tasks").insert(payload).select("id").single();if(r.error)return flash(r.error.message);if(!id&&role!=="admin"&&r.data?.id)notifyAdmin("task",r.data.id);$("modal").classList.add("hidden");await loadTasks();renderTasks();renderOverview()}}$("new-task-btn").onclick=()=>openTask("");
function renderChat(){const search=($("chat-search").value||"").toLowerCase();const readClient=role==="admin"?activeChatClient:me.client_id;if(readClient)supabase.rpc("mark_messages_read",{target_client_id:readClient}).then(async()=>{await loadMessages();if(currentSection==="chat")renderOverview()});if(role==="admin"){const active=activeClients(),archived=archivedClients(),all=[...active,...archived];if(!activeChatClient||!all.some(c=>c.client_id===activeChatClient))activeChatClient=active[0]?.client_id||archived[0]?.client_id||null;const archivedSelected=archived.some(c=>c.client_id===activeChatClient);$("chat-content").innerHTML=`<div class="chat-layout"><div class="client-list">${active.map(c=>`<button class="client-select ${c.client_id===activeChatClient?"active":""}" data-chat-client="${c.client_id}"><strong>${esc(c.full_name)}</strong><div class="client-meta">${esc(c.company_name||"No business name")}</div></button>`).join("")||"<div class='muted small' style='padding:12px'>No active clients.</div>"}${archived.length?`<details class="archive-panel" style="margin:12px"><summary>Archived Clients (${archived.length})</summary>${archived.map(c=>`<button class="client-select ${c.client_id===activeChatClient?"active":""}" data-chat-client="${c.client_id}"><strong>${esc(c.full_name)}</strong><div class="client-meta">${esc(c.company_name||"No business name")}</div></button>`).join("")}</details>`:""}</div>${chatPanel(activeChatClient,search,archivedSelected)}</div>`;document.querySelectorAll("[data-chat-client]").forEach(b=>b.onclick=()=>{activeChatClient=b.dataset.chatClient;renderChat()})}else $("chat-content").innerHTML=chatPanel(me.client_id,search,false);wireChat()}
function chatPanel(cid,search,readOnly=false){if(!cid)return"<div class='empty'>No client selected.</div>";const c=clientById(cid)||me,rows=messages.filter(m=>m.client_id===cid&&(!search||m.body.toLowerCase().includes(search)));return `<div class="chat-panel"><div class="chat-header"><strong>${esc(c.full_name)}</strong><div class="client-meta">${esc(c.company_name||"No business name")}${readOnly?" · Archived":""}</div></div><div class="chat-messages">${rows.map(m=>{const fromClient=m.sender_id===(c.id||me.id);const who=identityFor(m.sender_id);return `<div class="bubble ${fromClient?"client":"admin"}"><div class="message-sender">${identityBadge(m.sender_id,fromClient?c.full_name:"Haus Of Assistants")}</div><div>${esc(m.body)}</div><div class="meta">${fmtDate(m.created_at)}</div></div>`}).join("")||"<div class='muted'>No messages yet.</div>"}</div>${readOnly?"<div class='notice'>Archived conversation · read only</div>":`<form id="chat-form" class="chat-form"><textarea id="chat-input" required placeholder="Write a message…"></textarea><button class="primary">Send</button></form>`}</div>`}
function wireChat(){const form=$("chat-form");if(!form)return;const input=$("chat-input");if(input)input.onkeydown=e=>{if(e.key==="Enter"&&!e.shiftKey){e.preventDefault();if(input.value.trim())form.requestSubmit()}};form.onsubmit=async e=>{e.preventDefault();const body=$("chat-input").value.trim(),client_id=role==="admin"?activeChatClient:me.client_id;if(!body||!client_id)return;const r=await supabase.from("messages").insert({client_id,sender_id:session.user.id,body}).select("id").single();if(r.error)return flash(r.error.message);if(role!=="admin"&&r.data?.id)notifyAdmin("message",r.data.id);$("chat-input").value="";await loadMessages();renderChat();renderOverview()}}$("chat-search").oninput=renderChat;
function renderFiles(){const search=($("file-search").value||"").toLowerCase();const make=(c,archived=false)=>{const rows=files.filter(f=>f.client_id===c.client_id&&(!search||f.name.toLowerCase().includes(search)));return `<div class="client-section"><div class="client-heading"><div><h3>${esc(c.full_name)}</h3><div class="client-meta">${esc(c.company_name||"No business name")}${archived?" · Archived":""}</div></div>${!archived?`<label class="drop"><input class="client-file-input" data-file-client="${c.client_id}" type="file" multiple><strong>+ Upload files</strong></label>`:""}</div><div class="file-grid">${rows.map(f=>`<div class="file-card"><strong>${esc(f.name)}</strong><small>${fmtDate(f.created_at)}</small><div class="item-owner">Uploaded by ${identityBadge(f.uploaded_by)}</div><div class="table-actions" style="margin-top:10px"><button class="mini" data-preview-file="${f.id}">Preview</button><button class="mini" data-download="${f.id}">Download</button>${!archived?`<button class="mini" data-rename-file="${f.id}">Rename</button>`:""}${!archived?`<button class="mini danger" data-delete-file="${f.id}">Delete</button>`:""}</div></div>`).join("")||"<div class='muted'>No files yet.</div>"}</div></div>`};if(role==="admin"){const active=activeClients(),archived=archivedClients();$("files-content").innerHTML=(active.map(c=>make(c,false)).join("")||"<div class='empty'>No active clients.</div>")+(archived.length?`<details class="client-section archive-panel"><summary>Archived Clients (${archived.length})</summary>${archived.map(c=>make(c,true)).join("")}</details>`:"")}else $("files-content").innerHTML=make(me,false);wireFiles()}
function wireFiles(){document.querySelectorAll(".client-file-input").forEach(inp=>inp.onchange=e=>uploadFiles(e,inp.dataset.fileClient));document.querySelectorAll("[data-preview-file]").forEach(b=>b.onclick=()=>previewStoredFile(b.dataset.previewFile));document.querySelectorAll("[data-download]").forEach(b=>b.onclick=()=>downloadStoredFile(b.dataset.download));document.querySelectorAll("[data-rename-file]").forEach(b=>b.onclick=()=>renameStoredFile(b.dataset.renameFile));document.querySelectorAll("[data-delete-file]").forEach(b=>b.onclick=()=>deleteFile(b.dataset.deleteFile))}async function uploadFiles(e,cid){for(const file of e.target.files){const safe=file.name.replace(/[^a-zA-Z0-9._-]/g,"_"),path=`${cid}/files/${crypto.randomUUID()}-${safe}`;const up=await supabase.storage.from("client-files").upload(path,file);if(up.error){flash(up.error.message);continue}const ins=await supabase.from("files").insert({client_id:cid,name:file.name,path,content_type:file.type,size_bytes:file.size,uploaded_by:session.user.id});if(ins.error)flash(ins.error.message)}e.target.value="";await loadFiles();renderFiles()}async function previewStoredFile(id){const f=files.find(x=>x.id===id);if(!f)return;const r=await supabase.storage.from("client-files").createSignedUrl(f.path,300);if(r.error)return flash(r.error.message);const url=r.data.signedUrl,type=(f.content_type||"").toLowerCase(),name=esc(f.name);let body="";if(type.startsWith("image/"))body=`<div class="portal-preview-image-scroll"><img class="portal-preview-image" src="${url}" alt="${name}"></div>`;else if(type==="application/pdf"||f.name.toLowerCase().endsWith(".pdf"))body=`<iframe class="portal-preview-frame" src="${url}" title="${name}"></iframe>`;else if(type.startsWith("text/")){try{const res=await fetch(url),txt=await res.text();body=`<pre class="portal-preview-text">${esc(txt)}</pre>`}catch(e){body=`<div class="preview-fallback">This file cannot be previewed inside the portal. Use Download to open it.</div>`}}else body=`<div class="preview-fallback"><strong>${name}</strong><p>This file type cannot be previewed inside the portal. Use Download to open it.</p></div>`;showModal(`<div class="preview-head"><div><h2>File preview</h2><div class="muted small">${name}</div></div><button type="button" class="preview-x" onclick="closeModal()" aria-label="Close preview">×</button></div><div class="portal-preview">${body}</div>`,true)}async function renameStoredFile(id){const f=files.find(x=>x.id===id);if(!f)return;const next=prompt("New file name",f.name);if(!next||next.trim()===f.name)return;const clean=next.trim(),safe=clean.replace(/[^a-zA-Z0-9._-]/g,"_"),parts=f.path.split("/"),newPath=[...parts.slice(0,-1),crypto.randomUUID()+"-"+safe].join("/");const mv=await supabase.storage.from("client-files").move(f.path,newPath);if(mv.error)return flash(mv.error.message);const u=await supabase.from("files").update({name:clean,path:newPath}).eq("id",id);if(u.error){await supabase.storage.from("client-files").move(newPath,f.path);return flash(u.error.message)}await loadFiles();renderFiles();flash("File renamed.",true)}async function downloadStoredFile(id){const f=files.find(x=>x.id===id);if(!f)return;const r=await supabase.storage.from("client-files").createSignedUrl(f.path,300);if(r.error)return flash(r.error.message);window.open(r.data.signedUrl,"_blank")}async function deleteFile(id){if(!confirm("Delete this file?"))return;const f=files.find(x=>x.id===id);await supabase.storage.from("client-files").remove([f.path]);await supabase.from("files").delete().eq("id",id);await loadFiles();renderFiles()}$("file-search").oninput=renderFiles;

async function loadVaultCredentials(cid){vaultCredentials=[];if(!cid)return;const {data,error}=await supabase.rpc("list_client_credentials",{target_client_id:cid});if(error){flash(error.message);return}vaultCredentials=data||[]}
async function renderPasswords(){const active=role==="admin"?activeClients():[me];if(!active.length){$("passwords-content").innerHTML="<div class='empty'>No active clients.</div>";return}if(role==="admin"){if(!activeVaultClient||!active.some(c=>c.client_id===activeVaultClient))activeVaultClient=active[0].client_id}else activeVaultClient=me.client_id;await loadVaultCredentials(activeVaultClient);const picker=role==="admin"?`<div class="vault-picker"><label>Client<select id="vault-client-select">${active.map(c=>`<option value="${c.client_id}" ${c.client_id===activeVaultClient?"selected":""}>${esc(clientLabel(c.client_id))}</option>`).join("")}</select></label></div>`:"";const cards=vaultCredentials.map(v=>`<div class="vault-card"><div class="vault-icon">⌑</div><div class="vault-main"><strong>${esc(v.label)}</strong><span>${esc(v.username||"No username saved")}</span>${v.website?`<a href="${esc(/^https?:\/\//i.test(v.website)?v.website:"https://"+v.website)}" target="_blank" rel="noopener">Open website</a>`:""}${v.notes?`<small>${esc(v.notes)}</small>`:""}</div><div class="table-actions"><button class="mini" data-reveal-credential="${v.id}">Show / Copy</button><button class="mini" data-edit-credential="${v.id}">Edit</button><button class="mini danger" data-delete-credential="${v.id}">Delete</button></div></div>`).join("")||"<div class='empty'>No passwords saved for this client.</div>";$("passwords-content").innerHTML=picker+`<div class="vault-grid">${cards}</div>`;const sel=$("vault-client-select");if(sel)sel.onchange=()=>{activeVaultClient=sel.value;renderPasswords()};document.querySelectorAll("[data-reveal-credential]").forEach(b=>b.onclick=()=>reauthAndRevealCredential(b.dataset.revealCredential));document.querySelectorAll("[data-edit-credential]").forEach(b=>b.onclick=()=>openCredential(b.dataset.editCredential));document.querySelectorAll("[data-delete-credential]").forEach(b=>b.onclick=()=>deleteCredential(b.dataset.deleteCredential))}
function openCredential(id=""){const v=vaultCredentials.find(x=>x.id===id)||{};showModal(`<h2>${id?"Edit":"Add"} Password</h2><div class="notice">The password itself is encrypted and is never displayed in this form after saving.</div><form id="credential-form"><label>Account / service name<input id="v-label" required value="${esc(v.label||"")}" placeholder="e.g. Instagram"></label><label>Username or email<input id="v-user" value="${esc(v.username||"")}"></label><label>${id?"New password (leave blank to keep current)":"Password"}<input id="v-pass" type="password" autocomplete="new-password" ${id?"":"required"}></label><label>Website<input id="v-site" value="${esc(v.website||"")}" placeholder="https://"></label><label>Notes<textarea id="v-notes">${esc(v.notes||"")}</textarea></label><button class="primary">Save securely</button></form>`);$("credential-form").onsubmit=async e=>{e.preventDefault();const {error}=await supabase.rpc("save_client_credential",{target_client_id:activeVaultClient,credential_id:id||null,credential_label:$("v-label").value,credential_username:$("v-user").value,credential_password:$("v-pass").value,credential_website:$("v-site").value,credential_notes:$("v-notes").value});if(error)return flash(error.message);closeModal();await renderPasswords();flash("Password saved securely.",true)}}
async function reauthAndRevealCredential(id){showModal(`<h2>Confirm your identity</h2><div class="notice">Enter your Haus Of Assistants portal password to reveal this saved credential.</div><form id="reauth-form"><label>Portal password<input id="reauth-password" type="password" autocomplete="current-password" required></label><button class="primary">Reveal password</button></form>`);$("reauth-form").onsubmit=async e=>{e.preventDefault();const password=$("reauth-password").value;const auth=await supabase.auth.signInWithPassword({email:session.user.email,password});if(auth.error)return flash("Password confirmation failed.");session=auth.data.session||session;const r=await supabase.rpc("reveal_client_credential",{credential_id:id});if(r.error)return flash(r.error.message);const v=vaultCredentials.find(x=>x.id===id);showModal(`<h2>${esc(v?.label||"Saved password")}</h2><div class="revealed-secret"><span>Password</span><code id="revealed-password">${esc(r.data||"")}</code></div><button id="copy-revealed" class="primary">Copy password</button><div class="small muted" style="margin-top:12px">Close this window when finished. The password will be hidden again.</div>`);$("copy-revealed").onclick=async()=>{await navigator.clipboard.writeText(r.data||"");flash("Password copied.",true)}}}
async function deleteCredential(id){if(!confirm("Permanently delete this saved password? This cannot be undone."))return;const r=await supabase.rpc("delete_client_credential",{credential_id:id});if(r.error)return flash(r.error.message);await renderPasswords();flash("Saved password permanently deleted.",true)}
$("new-credential-btn").onclick=()=>{if(role==="admin"&&!activeVaultClient){const c=activeClients()[0];if(!c)return flash("Create an active client first.");activeVaultClient=c.client_id}else if(role!=="admin")activeVaultClient=me.client_id;openCredential("")};

function invoiceTable(rows,readOnly=false){return `<div class="table-wrap"><table class="table"><thead><tr><th>Invoice</th><th>Issue</th><th>Due</th><th>Amount</th><th>Status</th><th></th></tr></thead><tbody>${rows.map(i=>`<tr><td><strong>${esc(i.invoice_number)}</strong><div class="muted small">${esc(i.description||"")}</div><div class="item-owner">Uploaded by ${identityBadge(i.created_by)}</div></td><td>${fmtDate(i.issue_date)}</td><td>${fmtDate(i.due_date)}</td><td>${fmtMoney(i.amount)}</td><td><span class="badge ${String(i.status).toLowerCase()}">${esc(i.status)}</span></td><td><div class="table-actions">${(i.pdf_path||i.pdf_url)?`<button class="mini" data-invoice-preview="${i.id}">Preview</button><button class="mini" data-invoice-download="${i.id}">Download</button>`:""}${role==="admin"&&!readOnly?`<button class="mini" data-invoice-edit="${i.id}">Edit dates</button><button class="mini" data-invoice-status="${i.id}">Change status</button><button class="mini danger" data-invoice-delete="${i.id}">Delete</button>`:""}</div></td></tr>`).join("")||"<tr><td colspan='6' class='muted'>No invoices here.</td></tr>"}</tbody></table></div>`}
function renderInvoices(){const search=($("invoice-search").value||"").toLowerCase(),make=(c,archived=false)=>{const rows=invoices.filter(i=>i.client_id===c.client_id&&(!search||(i.invoice_number+" "+i.description).toLowerCase().includes(search))),open=rows.filter(i=>i.status!=="Paid"),paid=rows.filter(i=>i.status==="Paid");return `<div class="client-section"><div class="client-heading"><div><h3>${esc(c.full_name)}</h3><div class="client-meta">${esc(c.company_name||"No business name")}${archived?" · Archived":""}</div></div></div><h4>Current invoices</h4>${invoiceTable(open,archived)}<details class="archive-panel"><summary>Paid invoices (${paid.length})</summary>${invoiceTable(paid,archived)}</details></div>`};if(role==="admin"){const active=activeClients(),archived=archivedClients();$("invoices-content").innerHTML=(active.map(c=>make(c,false)).join("")||"<div class='empty'>No active clients.</div>")+(archived.length?`<details class="client-section archive-panel"><summary>Archived Clients (${archived.length})</summary>${archived.map(c=>make(c,true)).join("")}</details>`:"")}else $("invoices-content").innerHTML=make(me,false);document.querySelectorAll("[data-invoice-preview]").forEach(b=>b.onclick=()=>previewInvoice(b.dataset.invoicePreview));document.querySelectorAll("[data-invoice-download]").forEach(b=>b.onclick=()=>downloadInvoice(b.dataset.invoiceDownload));document.querySelectorAll("[data-invoice-edit]").forEach(b=>b.onclick=()=>editInvoiceDates(b.dataset.invoiceEdit));document.querySelectorAll("[data-invoice-status]").forEach(b=>b.onclick=()=>changeInvoiceStatus(b.dataset.invoiceStatus));document.querySelectorAll("[data-invoice-delete]").forEach(b=>b.onclick=()=>deleteInvoice(b.dataset.invoiceDelete))}$("invoice-search").oninput=renderInvoices;
$("new-invoice-btn").onclick=()=>{if(role!=="admin")return;showModal(`<h2>Upload Invoice</h2><form id="invoice-form"><label>Client<select id="i-client">${clients.filter(c=>c.status!=="Archived").map(c=>`<option value="${c.client_id}">${esc(clientLabel(c.client_id))}</option>`).join("")}</select></label><label>Invoice number<input id="i-num" required value="HOA-${Date.now().toString().slice(-6)}"></label><label>Description<input id="i-desc"></label><label>Amount (AUD)<input id="i-amount" type="number" step=".01" required></label><label>Issue date<input id="i-issue" type="date" value="${isoDate(new Date())}"></label><label>Due date<input id="i-due" type="date"></label><label>PDF invoice<input id="i-pdf" type="file" accept="application/pdf" required></label><button class="primary">Upload Invoice</button></form>`);$("invoice-form").onsubmit=uploadInvoice}
async function uploadInvoice(e){e.preventDefault();const cid=$("i-client").value,file=$("i-pdf").files[0];if(!file)return;const path=`${cid}/invoices/${crypto.randomUUID()}-${file.name.replace(/[^a-zA-Z0-9._-]/g,"_")}`;const up=await supabase.storage.from("client-files").upload(path,file);if(up.error)return flash(up.error.message);const r=await supabase.from("invoices").insert({client_id:cid,invoice_number:$("i-num").value,description:$("i-desc").value,amount:Number($("i-amount").value),issue_date:$("i-issue").value,due_date:$("i-due").value||null,status:"Outstanding",pdf_path:path,created_by:session.user.id});if(r.error)return flash(r.error.message);$("modal").classList.add("hidden");await loadInvoices();renderInvoices();renderOverview()}async function previewInvoice(id){const i=invoices.find(x=>x.id===id);if(!i)return;let url="";if(i.pdf_path){const r=await supabase.storage.from("client-files").createSignedUrl(i.pdf_path,300);if(r.error)return flash(r.error.message);url=r.data.signedUrl}else if(i.pdf_url)url=i.pdf_url;else return flash("No PDF is attached to this invoice.");showModal(`<div class="preview-head"><div><h2>Invoice preview</h2><div class="muted small">${esc(i.invoice_number||"Invoice")}</div></div><button type="button" class="preview-x" onclick="closeModal()" aria-label="Close preview">×</button></div><div class="portal-preview"><iframe class="portal-preview-frame" src="${url}#view=FitH" title="Invoice ${esc(i.invoice_number||"")}"></iframe></div>`,true)}async function downloadInvoice(id){const i=invoices.find(x=>x.id===id);if(!i)return;if(i.pdf_path){const r=await supabase.storage.from("client-files").createSignedUrl(i.pdf_path,300);if(r.error)return flash(r.error.message);window.open(r.data.signedUrl,"_blank");return}if(i.pdf_url){window.open(i.pdf_url,"_blank");return}flash("No PDF is attached to this invoice.")}async function editInvoiceDates(id){const i=invoices.find(x=>x.id===id);if(!i)return;showModal(`<h2>Edit invoice dates</h2><form id="invoice-dates-form"><label>Issue date<input id="edit-i-issue" type="date" value="${esc(i.issue_date||"")}"></label><label>Due date<input id="edit-i-due" type="date" value="${esc(i.due_date||"")}"></label><button class="primary">Save dates</button></form>`);$("invoice-dates-form").onsubmit=async e=>{e.preventDefault();const issue=$("edit-i-issue").value||null,due=$("edit-i-due").value||null;let nextStatus=i.status;if(i.status!=="Paid"&&i.status!=="Draft")nextStatus=due&&due<isoDate(new Date())?"Overdue":"Outstanding";const r=await supabase.from("invoices").update({issue_date:issue,due_date:due,status:nextStatus}).eq("id",id);if(r.error)return flash(r.error.message);closeModal();await loadInvoices();renderInvoices();renderOverview();flash("Invoice dates updated.",true)}}
async function deleteInvoice(id){const i=invoices.find(x=>x.id===id);if(!i||!confirm(`Permanently delete invoice ${i.invoice_number||""}? This will remove the invoice record and its uploaded PDF. This cannot be undone.`))return;if(i.pdf_path){const s=await supabase.storage.from("client-files").remove([i.pdf_path]);if(s.error)return flash("Invoice could not be deleted: "+s.error.message)}const r=await supabase.from("invoices").delete().eq("id",id);if(r.error)return flash(r.error.message);await loadInvoices();renderInvoices();renderOverview();flash("Invoice permanently deleted.",true)}
function changeInvoiceStatus(id){const i=invoices.find(x=>x.id===id);showModal(`<h2>Invoice status</h2><form id="status-form"><label>Status<select id="status-value">${["Draft","Outstanding","Overdue","Paid"].map(x=>`<option ${x===i.status?"selected":""}>${x}</option>`).join("")}</select></label><button class="primary">Save</button></form>`);$("status-form").onsubmit=async e=>{e.preventDefault();const r=await supabase.from("invoices").update({status:$("status-value").value}).eq("id",id);if(r.error)return flash(r.error.message);$("modal").classList.add("hidden");await loadInvoices();renderInvoices();renderOverview()}}
function renderTime(){const start=isoDate(monday()),make=(c,archived=false)=>{const used=hoursFor(c.client_id,start),allowed=Number(c.hours_per_week||0),pct=allowed?Math.min(100,used/allowed*100):0,logs=timeLogs.filter(x=>x.client_id===c.client_id&&x.work_date>=start&&x.work_date<=weekEnd(start)),reports=timeReports.filter(x=>x.client_id===c.client_id);return `<div class="client-section"><div class="client-heading"><div><h3>${esc(c.full_name)}</h3><div class="client-meta">${esc(c.company_name||"No business name")} · ${esc(c.package_name)} · ${allowed} hrs/week${archived?" · Archived":""}</div></div>${role==="admin"&&!archived?`<button class="mini" data-time-add="${c.client_id}">+ Log time</button>`:""}</div><div class="time-summary"><div class="time-box"><strong>${used.toFixed(2)} hrs</strong><div class="small muted">Used this week</div></div><div class="time-box"><strong>${Math.max(0,allowed-used).toFixed(2)} hrs</strong><div class="small muted">Remaining</div></div><div class="time-box"><strong>${start} → ${weekEnd(start)}</strong><div class="progress"><span style="width:${pct}%"></span></div></div></div>${taskTimeTable(logs,!archived)}<div class="week-report" style="margin-top:14px">${role==="admin"&&!archived?`<button class="primary beige" data-close-week="${c.client_id}">Create weekly PDF</button>`:""}${reports.length?`<div class="report-archive report-list"><div class="report-list-title">Previous weekly reports <span>${reports.length}</span></div>${reports.map(r=>`<div class="report-row"><div><strong>${fmtDate(r.week_start)} - ${fmtDate(r.week_end)}</strong><small>${(Number(r.total_minutes||0)/60).toFixed(2)} hrs tracked</small></div><div class="table-actions"><button class="mini" data-report-preview="${r.id}">Preview</button><button class="mini" data-report-download="${r.id}">Download</button>${role==="admin"?`<button class="mini danger" data-report-delete="${r.id}">Delete</button>`:""}</div></div>`).join("")}</div>`:""}</div></div>`};if(role==="admin"){const active=activeClients(),archived=archivedClients();$("time-content").innerHTML=(active.map(c=>make(c,false)).join("")||"<div class='empty'>No active clients.</div>")+(archived.length?`<details class="client-section archive-panel"><summary>Archived Clients (${archived.length})</summary>${archived.map(c=>make(c,true)).join("")}</details>`:"")}else $("time-content").innerHTML=make(me,false);document.querySelectorAll("[data-time-add]").forEach(b=>b.onclick=()=>openTimeLog(b.dataset.timeAdd));document.querySelectorAll("[data-close-week]").forEach(b=>b.onclick=()=>createWeeklyPdf(b.dataset.closeWeek,start));document.querySelectorAll("[data-report-preview]").forEach(b=>b.onclick=()=>previewReport(b.dataset.reportPreview));document.querySelectorAll("[data-report-download]").forEach(b=>b.onclick=()=>downloadReport(b.dataset.reportDownload));document.querySelectorAll("[data-report-delete]").forEach(b=>b.onclick=()=>deleteReport(b.dataset.reportDelete));document.querySelectorAll("[data-time-delete]").forEach(b=>b.onclick=()=>deleteTimeLog(b.dataset.timeDelete))}
function taskTimeTable(rows,allowDelete=true){return `<div class="table-wrap"><table class="table"><thead><tr><th>Date</th><th>Work completed</th><th>Time</th>${role==="admin"?"<th></th>":""}</tr></thead><tbody>${rows.map(x=>`<tr><td>${fmtDate(x.work_date)}</td><td>${esc(x.description)}<div class="item-owner">Logged by ${identityBadge(x.created_by)}</div></td><td>${(Number(x.minutes)/60).toFixed(2)} hrs</td>${role==="admin"?(allowDelete?`<td><button class="mini" data-time-delete="${x.id}">Delete</button></td>`:"<td></td>"):""}</tr>`).join("")||`<tr><td colspan="4" class="muted">No time logged this week.</td></tr>`}</tbody></table></div>`}
$("new-time-btn").onclick=()=>{if(role!=="admin")return;const c=clients.find(x=>x.status!=="Archived");if(c)openTimeLog(c.client_id)};function openTimeLog(cid){showModal(`<h2>Add time log</h2><form id="time-form"><label>Client<select id="t-client">${clients.filter(c=>c.status!=="Archived").map(c=>`<option value="${c.client_id}" ${c.client_id===cid?"selected":""}>${esc(clientLabel(c.client_id))}</option>`).join("")}</select></label><label>Date<input id="t-date" type="date" value="${isoDate(new Date())}" required></label><label>What was completed?<textarea id="t-desc" required></textarea></label><label>Minutes<input id="t-min" type="number" min="1" step="1" required></label><button class="primary">Add log</button></form>`);$("time-form").onsubmit=async e=>{e.preventDefault();const r=await supabase.from("time_logs").insert({client_id:$("t-client").value,work_date:$("t-date").value,description:$("t-desc").value.trim(),minutes:Number($("t-min").value),created_by:session.user.id});if(r.error)return flash(r.error.message);$("modal").classList.add("hidden");await loadTime();renderTime()}}
async function deleteTimeLog(id){if(role!=="admin"||!confirm("Delete this time log?"))return;const r=await supabase.from("time_logs").delete().eq("id",id);if(r.error)return flash(r.error.message);await loadTime();renderTime()}
async function createWeeklyPdf(cid,start){const c=clientById(cid),end=weekEnd(start),logs=timeLogs.filter(x=>x.client_id===cid&&x.work_date>=start&&x.work_date<=end),total=logs.reduce((a,b)=>a+Number(b.minutes||0),0);if(!logs.length)return flash("There are no time logs for this week yet.");const doc=new jsPDF();try{const logoRes=await fetch("haus-of-assistants-logo.png"),logoBlob=await logoRes.blob(),logoData=await new Promise((resolve,reject)=>{const fr=new FileReader();fr.onload=()=>resolve(fr.result);fr.onerror=reject;fr.readAsDataURL(logoBlob)});const props=doc.getImageProperties(logoData),maxW=58,maxH=24,scale=Math.min(maxW/props.width,maxH/props.height),w=props.width*scale,h=props.height*scale;doc.addImage(logoData,"PNG",(210-w)/2,12,w,h)}catch(e){}doc.setFontSize(18);doc.text("Weekly Time Report",105,43,{align:"center"});doc.setFontSize(11);doc.text(`${c.full_name} | ${c.company_name||""}`,20,54);doc.text(`${start} to ${end} | ${c.package_name} | ${c.hours_per_week} hours allocated`,20,61);let y=74;for(const l of logs){const lines=doc.splitTextToSize(`${l.work_date} | ${(l.minutes/60).toFixed(2)} hrs | ${l.description}`,170);doc.text(lines,20,y);y+=lines.length*6+4;if(y>275){doc.addPage();y=20}}doc.setFontSize(12);doc.text(`Total used: ${(total/60).toFixed(2)} hours`,20,y+6);const blob=doc.output("blob"),path=`${cid}/time-reports/${start}.pdf`;const up=await supabase.storage.from("client-files").upload(path,blob,{contentType:"application/pdf",upsert:true});if(up.error)return flash(up.error.message);const r=await supabase.from("time_week_reports").upsert({client_id:cid,week_start:start,week_end:end,total_minutes:total,pdf_path:path,created_by:session.user.id},{onConflict:"client_id,week_start"});if(r.error)return flash(r.error.message);await loadTime();renderTime();flash("Weekly PDF created and saved to this client.",true)}async function previewReport(id){const r=timeReports.find(x=>x.id===id);if(!r)return;const u=await supabase.storage.from("client-files").createSignedUrl(r.pdf_path,300);if(u.error)return flash(u.error.message);showModal(`<div class="preview-head"><div><h2>Time report preview</h2><div class="muted small">Week ${fmtDate(r.week_start)}</div></div><button type="button" class="preview-x" onclick="closeModal()" aria-label="Close preview">×</button></div><div class="portal-preview"><iframe class="portal-preview-frame" src="${u.data.signedUrl}#view=FitH" title="Time report"></iframe></div>`,true)}async function downloadReport(id){const r=timeReports.find(x=>x.id===id);if(!r)return;const u=await supabase.storage.from("client-files").createSignedUrl(r.pdf_path,300);if(u.error)return flash(u.error.message);window.open(u.data.signedUrl,"_blank")}
async function deleteReport(id){if(role!=="admin")return;const r=timeReports.find(x=>x.id===id);if(!r||!confirm(`Permanently delete the weekly time report for ${fmtDate(r.week_start)}? This removes the saved PDF and cannot be undone.`))return;if(r.pdf_path){const s=await supabase.storage.from("client-files").remove([r.pdf_path]);if(s.error)return flash("Time report could not be deleted: "+s.error.message)}const d=await supabase.from("time_week_reports").delete().eq("id",id);if(d.error)return flash(d.error.message);await loadTime();renderTime();flash("Weekly time report deleted.",true)}
function renderClients(){if(role!=="admin")return;const make=(title,rows,archived)=>`<div class="client-section"><div class="group-heading"><h3>${title}</h3><span class="muted small">${rows.length} client${rows.length===1?"":"s"}</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Client</th><th>Business</th><th>Package</th><th>Hours</th><th>Status</th><th></th></tr></thead><tbody>${rows.map(c=>`<tr><td><strong>${esc(c.full_name)}</strong><div class="muted small">${esc(c.email)}</div></td><td>${esc(c.company_name||"—")}</td><td>${esc(c.package_name)}</td><td>${c.hours_per_week}</td><td><span class="badge ${archived?"archived":"active"}">${esc(c.status)}</span></td><td><div class="table-actions"><button class="mini" data-edit-client="${c.client_id}">Manage</button><button class="mini ${archived?"":"danger"}" data-archive-client="${c.client_id}" data-action="${archived?"restore":"archive"}">${archived?"Restore":"Archive"}</button></div></td></tr>`).join("")||"<tr><td colspan='6' class='muted'>None.</td></tr>"}</tbody></table></div></div>`;$("clients-content").innerHTML=make("Active clients",clients.filter(c=>c.status!=="Archived"),false)+make("Archived clients",clients.filter(c=>c.status==="Archived"),true);document.querySelectorAll("[data-edit-client]").forEach(b=>b.onclick=()=>editClient(b.dataset.editClient));document.querySelectorAll("[data-archive-client]").forEach(b=>b.onclick=()=>archiveClient(b.dataset.archiveClient,b.dataset.action))}
$("new-client-btn").onclick=()=>showCreateClient();function showCreateClient(){showModal(`<h2>Create client</h2><div class="notice">A temporary password is generated securely and shown once.</div><form id="client-form"><label>Client name<input id="c-name" required></label><label>Email<input id="c-email" type="email" required></label><label>Company name<input id="c-company"></label><label>Phone<input id="c-phone"></label><label>Package<select id="c-package"><option>Essential</option><option>Professional</option><option>Premium</option></select></label><label>Hours per week<input id="c-hours" type="number" min="0" step=".5" value="3"></label><button class="primary">Create Client</button></form>`);$("client-form").onsubmit=createClientAccount}async function createClientAccount(e){e.preventDefault();const payload={email:$("c-email").value.trim().toLowerCase(),full_name:$("c-name").value.trim(),company_name:$("c-company").value.trim(),phone:$("c-phone").value.trim(),package_name:$("c-package").value,hours_per_week:Number($("c-hours").value)};const {data,error}=await supabase.functions.invoke("Create-user",{body:payload});if(error||!data?.success)return flash(`Create client failed: ${data?.details||error?.message||"Unknown error"}`);$("modal-body").innerHTML=`<h2>Client created</h2><div class="notice"><strong>Email:</strong> ${esc(data.email)}<br><strong>Temporary password:</strong> ${esc(data.temp_password)}</div><button class="primary" id="close-created">Done</button>`;$("close-created").onclick=async()=>{$("modal").classList.add("hidden");await loadClients();renderClients()}}
function editClient(id){const c=clientById(id);showModal(`<h2>Manage client</h2><form id="edit-client"><label>Full name<input id="ec-name" value="${esc(c.full_name)}"></label><label>Company<input id="ec-company" value="${esc(c.company_name)}"></label><label>Phone<input id="ec-phone" value="${esc(c.phone)}"></label><label>Package<select id="ec-package">${["Essential","Professional","Premium"].map(x=>`<option ${x===c.package_name?"selected":""}>${x}</option>`).join("")}</select></label><label>Hours/week<input id="ec-hours" type="number" step=".5" value="${c.hours_per_week}"></label><button class="primary">Save changes</button></form>`);$("edit-client").onsubmit=async e=>{e.preventDefault();const r=await supabase.from("profiles").update({full_name:$("ec-name").value,company_name:$("ec-company").value,phone:$("ec-phone").value,package_name:$("ec-package").value,hours_per_week:Number($("ec-hours").value)}).eq("client_id",id);if(r.error)return flash(r.error.message);$("modal").classList.add("hidden");await loadClients();renderClients()}}
async function archiveClient(cid,action){const c=clientById(cid);if(!confirm(action==="archive"?`Archive ${c.full_name}? Their portal login will be disabled and ALL saved Password Vault credentials will be permanently deleted. Other archived records will be retained.`:`Restore ${c.full_name}?`))return;const {data,error}=await supabase.functions.invoke("manage-client",{body:{client_id:cid,action}});if(error||!data?.success)return flash(data?.details||error?.message||"Client status could not be changed.");await loadClients();renderClients();flash(action==="archive"?"Client archived. Their login is disabled, other records are retained, and saved passwords have been permanently deleted.":"Client restored and login re-enabled.",true)}
async function renderAvatar(p=me){if(!p)return;let src="";if(p.avatar_path){const s=await supabase.storage.from("avatars").createSignedUrl(p.avatar_path,3600);src=s.data?.signedUrl||""}let img=$("side-avatar");if(!img){img=document.createElement("img");img.id="side-avatar";img.className="profile-avatar";document.querySelector(".userbox")?.prepend(img)}img.src=src||"default-avatar.svg";img.alt=(p.full_name||"Profile")+" profile picture"}function renderProfile(){if(!me)return;$("profile-name").value=me.full_name||"";$("profile-business").value=me.company_name||"";$("profile-phone").value=me.phone||"";if(!$("avatar-upload-wrap")){$("profile-form").insertAdjacentHTML("afterbegin",`<div id="avatar-upload-wrap" class="avatar-upload"><img id="account-avatar" class="account-avatar" alt="Profile picture"><div><label>Profile picture<input id="profile-avatar-input" type="file" accept="image/jpeg,image/png,image/webp"></label><div class="small muted">JPG, PNG or WebP, up to 5 MB.</div><button id="remove-profile-avatar" type="button" class="mini">Remove photo</button></div></div>`);$("profile-avatar-input").onchange=uploadAvatar;$("remove-profile-avatar").onclick=removeAvatar}renderAccountAvatar()}async function renderAccountAvatar(){if(!$("account-avatar"))return;let src="";if(me.avatar_path){const s=await supabase.storage.from("avatars").createSignedUrl(me.avatar_path,3600);src=s.data?.signedUrl||""}$("account-avatar").src=src||"default-avatar.svg"}async function removeAvatar(){if(!me.avatar_path)return flash("You are already using the default profile picture.");if(!confirm("Remove your profile picture and return to the default image?"))return;const old=me.avatar_path;const r=await supabase.from("profiles").update({avatar_path:null}).eq("id",me.id);if(r.error)return flash(r.error.message);await supabase.storage.from("avatars").remove([old]);me={...me,avatar_path:null};await renderAvatar(me);await renderAccountAvatar();flash("Profile picture removed.",true)}async function uploadAvatar(e){const file=e.target.files?.[0];if(!file)return;if(file.size>5242880)return flash("Profile picture must be 5 MB or smaller.");const ext=(file.name.split(".").pop()||"jpg").toLowerCase(),path=`${session.user.id}/avatar-${Date.now()}.${ext}`;const up=await supabase.storage.from("avatars").upload(path,file,{contentType:file.type,upsert:false});if(up.error)return flash(up.error.message);const old=me.avatar_path;const r=await supabase.from("profiles").update({avatar_path:path}).eq("id",me.id);if(r.error){await supabase.storage.from("avatars").remove([path]);return flash(r.error.message)}if(old)await supabase.storage.from("avatars").remove([old]);me={...me,avatar_path:path};await renderAvatar(me);await renderAccountAvatar();flash("Profile picture updated.",true)}$("profile-form").onsubmit=async e=>{e.preventDefault();const r=await supabase.from("profiles").update({full_name:$("profile-name").value,company_name:$("profile-business").value,phone:$("profile-phone").value}).eq("id",me.id);if(r.error)return flash(r.error.message);me={...me,full_name:$("profile-name").value,company_name:$("profile-business").value,phone:$("profile-phone").value};$("side-name").textContent=me.full_name;flash("Profile saved.",true)};$("password-form").onsubmit=async e=>{e.preventDefault();if($("new-password").value!==$("confirm-password").value)return flash("Passwords do not match.");const r=await supabase.auth.updateUser({password:$("new-password").value});if(r.error)return flash(r.error.message);e.currentTarget.reset();flash("Password updated.",true)};
async function notifyAdmin(event_type,source_id){try{await supabase.functions.invoke("notify-admin",{body:{event_type,source_id}})}catch(e){console.warn("Admin email notification could not be sent",e)}}
function setupNotificationUI(){if($("hoa-notify-wrap"))return;const style=document.createElement("style");style.textContent=`#hoa-notify-wrap{position:fixed;right:24px;top:18px;z-index:80}#hoa-notify-btn{width:44px;height:44px;border-radius:50%;border:1px solid #d8d0c6;background:#fff;font-size:20px;cursor:pointer;box-shadow:0 8px 24px #0001;position:relative}#hoa-notify-count{position:absolute;right:-4px;top:-5px;min-width:19px;height:19px;padding:0 5px;border-radius:10px;background:#171717;color:#fff;font:11px/19px Arial;text-align:center}#hoa-notify-panel{position:absolute;right:0;top:52px;width:min(380px,88vw);max-height:520px;overflow:auto;background:#fff;border:1px solid #ded9d1;box-shadow:0 18px 45px #0002;padding:14px}#hoa-notify-panel.hidden{display:none}.hoa-note{padding:12px;border-bottom:1px solid #eee;cursor:pointer}.hoa-note.unread{background:#f5f0e9}.hoa-note small{display:block;color:#777;margin-top:5px}`;document.head.appendChild(style);const w=document.createElement("div");w.id="hoa-notify-wrap";w.innerHTML=`<button id="hoa-notify-btn" aria-label="Notifications">🔔<span id="hoa-notify-count" style="display:none">0</span></button><div id="hoa-notify-panel" class="hidden"><div style="display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:8px"><strong>Notifications</strong><button class="mini" id="hoa-mark-all">Mark all read</button></div><div id="hoa-notify-list"></div></div>`;document.body.appendChild(w);$("hoa-notify-btn").onclick=()=>$("hoa-notify-panel").classList.toggle("hidden");$("hoa-mark-all").onclick=markAllNotificationsRead}
async function loadNotifications(){if(role!=="admin")return;const r=await supabase.from("admin_notifications").select("*").order("created_at",{ascending:false}).limit(50);notifications=r.data||[];renderNotifications()}
function renderNotifications(){if(role!=="admin"||!$("hoa-notify-list"))return;const unread=notifications.filter(n=>!n.is_read).length;$("hoa-notify-count").textContent=unread;$("hoa-notify-count").style.display=unread?"block":"none";$("hoa-notify-list").innerHTML=notifications.map(n=>`<div class="hoa-note ${n.is_read?"":"unread"}" data-note="${n.id}" data-note-type="${esc(n.event_type)}" data-note-client="${esc(n.client_id)}"><strong>${esc(n.title)}</strong><div>${esc(n.body||"")}</div><small>${new Date(n.created_at).toLocaleString("en-AU")}</small></div>`).join("")||"<div class='muted small'>No notifications yet.</div>";document.querySelectorAll("[data-note]").forEach(x=>x.onclick=async()=>{await supabase.from("admin_notifications").update({is_read:true}).eq("id",x.dataset.note);if(x.dataset.noteType==="message"){activeChatClient=x.dataset.noteClient;go("chat")}else go("tasks");await loadNotifications()})}
async function markAllNotificationsRead(){await supabase.from("admin_notifications").update({is_read:true}).eq("is_read",false);await loadNotifications()}
function subscribeRealtime(){if(channel)supabase.removeChannel(channel);channel=supabase.channel("hoa-portal-"+me.id).on("postgres_changes",{event:"*",schema:"public",table:"messages"},async()=>{await loadMessages();if(currentSection==="chat")renderChat();renderOverview()}).on("postgres_changes",{event:"*",schema:"public",table:"tasks"},async()=>{await loadTasks();if(currentSection==="tasks")renderTasks();renderOverview()}).on("postgres_changes",{event:"*",schema:"public",table:"invoices"},async()=>{await loadInvoices();if(currentSection==="invoices")renderInvoices();renderOverview()}).on("postgres_changes",{event:"*",schema:"public",table:"files"},async()=>{await loadFiles();if(currentSection==="files")renderFiles()}).on("postgres_changes",{event:"*",schema:"public",table:"time_logs"},async()=>{await loadTime();if(currentSection==="time")renderTime();renderOverview()}).on("postgres_changes",{event:"*",schema:"public",table:"time_week_reports"},async()=>{await loadTime();if(currentSection==="time")renderTime()}).on("postgres_changes",{event:"INSERT",schema:"public",table:"admin_notifications"},async()=>{if(role==="admin")await loadNotifications()}).subscribe()}
supabase?.auth.onAuthStateChange((_event,s)=>{session=s});boot();
